func WalkDir(root string, fn fs.WalkDirFunc) error {
	info, err := os.Lstat(root)
	if err != nil {
		err = fn(root, nil, err)
	} else {
		err = walkDir(root, &statDirEntry{info}, fn) 
	}
	if err == SkipDir {
		return nil
	}
	return err
}
```

Only one line here has `err != nil`: 

```go
		err = fn(root, nil, err) 
```

but you can see that this implies that the `path == root` and therefore this code is correct.

Then we look at `walkDir`:

```go
// walkDir recursively descends path, calling walkDirFn.
func walkDir(path string, d fs.DirEntry, walkDirFn fs.WalkDirFunc) error {
	if err := walkDirFn(path, d, nil); err != nil || !d.IsDir() { 
		if err == SkipDir && d.IsDir() {
			// Successfully skipped directory.
			err = nil
		}
		return err
	}

	dirs, err := readDir(path)
	if err != nil {
		// Second call, to report ReadDir error.
		err = walkDirFn(path, d, err)
		if err != nil {
			return err
		}
	}

	for _, d1 := range dirs {
		path1 := Join(path, d1.Name())
		if err := walkDir(path1, d1, walkDirFn); err != nil {
			if err == SkipDir {
				break
			}
			return err
		}
	}
	return nil
}
```

Again only one line has `err != nil`:

```go
		err = walkDirFn(path, d, err)
```

and again the `path` is always set (and will always have root as a prefix)

We calculate the name before checking the error because the error code uses this name in its logging.

It is therefore safe to defer checking the error until after we have done this calculation.

